-- A reader for unchanged local Workshop source fixtures generated by the test
-- runner. Production uses the game's getModFileReader against B42_PZLinux.
if getModFileReader then return end
require "pzlinux-native-sources"
function getModFileReader(mod, path, create)
    assert(mod=="B42_PZLinux" and create==false)
    local source=assert(KnightsNativeSources[path],"Missing native source fixture: "..path)
    local lines={}
    for line in (source.."\n"):gmatch("(.-)\n") do lines[#lines+1]=line end
    local index=0
    return {readLine=function() index=index+1; return lines[index] end,close=function() end}
end
